/* =====================================================================
   DB_FINANC_II — script convertido de SQL Server (T-SQL) para MySQL 8.0+
   Ferramenta alvo: MySQL Workbench
   Requisitos: MySQL 8.0.16 ou superior (DEFAULT com expressão e CHECK)
   ===================================================================== */

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

/*--- -------------------------------------------------------------------------*/
CREATE DATABASE IF NOT EXISTS DB_FINANC_II
  DEFAULT CHARACTER SET utf8mb4
  DEFAULT COLLATE utf8mb4_0900_ai_ci;

USE DB_FINANC_II;

/*--- -------------------------------------------------------------------------*/
CREATE TABLE CLIENTE (
  ID_CLIENTE     INT          NOT NULL AUTO_INCREMENT PRIMARY KEY,
  NOME           VARCHAR(120) NOT NULL,
  EMAIL          VARCHAR(160) NOT NULL UNIQUE,
  CPF            VARCHAR(14)  NULL,
  SEGMENTO       VARCHAR(20)  NULL, -- 'varejo','vip','prime'
  SCORE_CREDITO  INT          NULL,
  DATA_CADASTRO  DATE         NOT NULL DEFAULT (CURRENT_DATE)
) ENGINE = InnoDB;

/*--- -------------------------------------------------------------------------*/
CREATE TABLE AGENCIA (
  ID_AGENCIA  INT         NOT NULL AUTO_INCREMENT PRIMARY KEY,
  NOME        VARCHAR(80) NOT NULL,
  CIDADE      VARCHAR(80) NOT NULL,
  UF          CHAR(2)     NULL
) ENGINE = InnoDB;

/*--- -------------------------------------------------------------------------*/
CREATE TABLE CONTA (
  ID_CONTA       INT           NOT NULL AUTO_INCREMENT PRIMARY KEY,
  ID_CLIENTE     INT           NOT NULL,
  ID_AGENCIA     INT           NOT NULL,
  TIPO_CONTA     VARCHAR(20)   NOT NULL DEFAULT 'CORRENTE',
  DATA_ABERTURA  DATE          NOT NULL DEFAULT (CURRENT_DATE),
  SALDO          DECIMAL(14,2) NOT NULL DEFAULT 0,
  STATUS         VARCHAR(20)   NOT NULL DEFAULT 'ATIVA',
  CONSTRAINT CK_CONTA_TIPO   CHECK (TIPO_CONTA IN ('CORRENTE','POUPANCA','SALARIO','INVESTIMENTO')),
  CONSTRAINT CK_CONTA_STATUS CHECK (STATUS IN ('ATIVA','BLOQUEADA','ENCERRADA')),
  CONSTRAINT FK_CONTA_CLIENTE FOREIGN KEY (ID_CLIENTE) REFERENCES CLIENTE(ID_CLIENTE),
  CONSTRAINT FK_CONTA_AGENCIA FOREIGN KEY (ID_AGENCIA) REFERENCES AGENCIA(ID_AGENCIA)
) ENGINE = InnoDB;

/*--- -------------------------------------------------------------------------*/
CREATE TABLE KYC_CLIENTE (
  ID_CLIENTE        INT         NOT NULL PRIMARY KEY,
  NIVEL             VARCHAR(16) NOT NULL DEFAULT 'BASICO',
  RISCO             VARCHAR(16) NOT NULL DEFAULT 'BAIXO',
  PEP               TINYINT(1)  NOT NULL DEFAULT 0, -- BIT do SQL Server
  DATA_ATUALIZACAO  DATE        NOT NULL DEFAULT (CURRENT_DATE),
  CONSTRAINT CK_KYC_NIVEL CHECK (NIVEL IN ('BASICO','COMPLETO')),
  CONSTRAINT CK_KYC_RISCO CHECK (RISCO IN ('BAIXO','MEDIO','ALTO')),
  CONSTRAINT FK_KYC_CLIENTE FOREIGN KEY (ID_CLIENTE) REFERENCES CLIENTE(ID_CLIENTE)
) ENGINE = InnoDB;

/*--- -------------------------------------------------------------------------*/
CREATE TABLE CARTAO (
  ID_CARTAO       INT           NOT NULL AUTO_INCREMENT PRIMARY KEY,
  ID_CLIENTE      INT           NOT NULL,
  BANDEIRA        VARCHAR(20)   NOT NULL,
  LIMITE          DECIMAL(14,2) NOT NULL DEFAULT 0,
  FECHAMENTO_DIA  INT           NOT NULL,
  VENCIMENTO_DIA  INT           NOT NULL,
  STATUS          VARCHAR(20)   NOT NULL DEFAULT 'ATIVO',
  CONSTRAINT CK_CARTAO_STATUS CHECK (STATUS IN ('ATIVO','BLOQUEADO','CANCELADO')),
  CONSTRAINT FK_CARTAO_CLIENTE FOREIGN KEY (ID_CLIENTE) REFERENCES CLIENTE(ID_CLIENTE)
) ENGINE = InnoDB;

/*--- -------------------------------------------------------------------------*/
CREATE TABLE EMPRESTIMO (
  ID_EMPRESTIMO     INT           NOT NULL AUTO_INCREMENT PRIMARY KEY,
  ID_CLIENTE        INT           NOT NULL,
  TIPO              VARCHAR(20)   NOT NULL,
  VALOR_CONTRATADO  DECIMAL(14,2) NOT NULL,
  SALDO_DEVEDOR     DECIMAL(14,2) NOT NULL,
  -- TAXA_MENSAL    DECIMAL(9,6)  NOT NULL DEFAULT 0,
  DATA_CONTRATACAO  DATE          NOT NULL DEFAULT (CURRENT_DATE),
  STATUS            VARCHAR(20)   NOT NULL DEFAULT 'ATIVO',
  CONSTRAINT CK_EMPRESTIMO_STATUS CHECK (STATUS IN ('ATIVO','LIQUIDADO','ATRASO')),
  CONSTRAINT FK_EMPRESTIMO_CLIENTE FOREIGN KEY (ID_CLIENTE) REFERENCES CLIENTE(ID_CLIENTE)
) ENGINE = InnoDB;

/*--- -------------------------------------------------------------------------*/
CREATE TABLE PARCELA_EMPRESTIMO (
  ID_PARCELA       INT           NOT NULL AUTO_INCREMENT PRIMARY KEY,
  ID_EMPRESTIMO    INT           NOT NULL,
  NUMERO           INT           NOT NULL,
  VALOR            DECIMAL(14,2) NULL,
  VALOR_PAGO       DECIMAL(14,2) NULL,
  DATA_VENCIMENTO  DATE          NOT NULL,
  DATA_PAGAMENTO   DATE          NULL,
  STATUS           VARCHAR(20)   NOT NULL DEFAULT 'ABERTA',
  CONSTRAINT CK_PARCELA_STATUS CHECK (STATUS IN ('ABERTA','PAGA','ATRASADA')),
  CONSTRAINT FK_PARCELA_EMP FOREIGN KEY (ID_EMPRESTIMO) REFERENCES EMPRESTIMO(ID_EMPRESTIMO)
) ENGINE = InnoDB;

/*--- -------------------------------------------------------------------------*/
CREATE TABLE TRANSACAO (
  ID_TRANSACAO      BIGINT        NOT NULL AUTO_INCREMENT PRIMARY KEY,
  ID_CONTA_ORIGEM   INT           NULL,
  ID_CONTA_DESTINO  INT           NULL,
  TIPO              VARCHAR(20)   NOT NULL,
  VALOR             DECIMAL(14,2) NOT NULL,
  DATA_TRANSACAO    DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  DESCRICAO         VARCHAR(255)  NULL,
  CONSTRAINT CK_TRANS_TIPO CHECK (TIPO IN ('PIX','TED','DEPOSITO','SAQUE','PAGAMENTO','TARIFA','JUROS')),
  CONSTRAINT FK_TRANS_ORIGEM  FOREIGN KEY (ID_CONTA_ORIGEM)  REFERENCES CONTA(ID_CONTA),
  CONSTRAINT FK_TRANS_DESTINO FOREIGN KEY (ID_CONTA_DESTINO) REFERENCES CONTA(ID_CONTA)
) ENGINE = InnoDB;

CREATE INDEX IX_TRANS_DATA    ON TRANSACAO (DATA_TRANSACAO);
CREATE INDEX IX_TRANS_TIPO    ON TRANSACAO (TIPO);
CREATE INDEX IX_TRANS_ORIGEM  ON TRANSACAO (ID_CONTA_ORIGEM);
CREATE INDEX IX_TRANS_DESTINO ON TRANSACAO (ID_CONTA_DESTINO);

/*--- -------------------------------------------------------------------------*/
CREATE TABLE COMPRA_CARTAO (
  ID_COMPRA        BIGINT        NOT NULL AUTO_INCREMENT PRIMARY KEY,
  ID_CARTAO        INT           NOT NULL,
  ESTABELECIMENTO  VARCHAR(20)   NOT NULL DEFAULT 'Estabelecimento nnnn',
  CATEGORIA        VARCHAR(20)   NOT NULL DEFAULT 'Categoria xxxx',
  VALOR            DECIMAL(14,2) NULL,
  PARCELAS         DECIMAL(14,2) NULL,
  STATUS           VARCHAR(20)   NOT NULL DEFAULT 'LANÇADA',
  DATA_COMPRA      DATE          NOT NULL DEFAULT (CURRENT_DATE),
  CONSTRAINT CK_COMPRA_STATUS CHECK (STATUS IN ('LANÇADA','FATURADA','PAGA','ESTORNADA')),
  CONSTRAINT FK_COMPRA_CARTAO FOREIGN KEY (ID_CARTAO) REFERENCES CARTAO(ID_CARTAO)
) ENGINE = InnoDB;

/*--- -------------------------------------------------------------------------*/
